// NOTE: @/lib/supabase is intentionally mocked only by supabase-test-preload.ts.
// bunfig.toml loads that dedicated preload first. Registering a second mock here
// creates an export race and can hide named exports such as getSupabaseClient.

// ---------------------------------------------------------------------------
// Partial mocks must not DELETE exports other test files depend on.
//
// `mock.module()` is process-global and last-write-wins, and bun runs every
// test file in one process. A file that mocked only the two exports it cared
// about therefore replaced the module for the whole run, and an unrelated file
// importing a third export died at link time with
//   "SyntaxError: Export named 'X' not found in module 'Y'"
// reported as an "Unhandled error between tests" with no failing test name --
// so the suite was red while every (fail) marker was absent.
//
// Two real cases this fixes:
//   * 7 chat tests mock 'react-native' without TextInput ->
//     text-node-guard-render-props.test.ts could not import TextInput.
//   * chat-streaming-ux-p0.test.ts mocks ivxOwnerMemoryService with 2 exports ->
//     ivx-multimodal-upload.test.ts lost createIVXOwnerMultiFileUnderstandingPrompt.
//
// The wrapper below layers each later factory OVER a base (the preload baseline
// if we registered one, otherwise the real module). The caller's exports always
// win, so no test's intent is weakened -- absent keys simply survive.
// ---------------------------------------------------------------------------
type ModuleExports = Record<string, unknown>;

const mockRegistry = mock as unknown as {
  module: (specifier: string, factory: () => unknown) => void;
};
const baselineExports = new Map<string, ModuleExports>();
const originalMockModule = mockRegistry.module.bind(mockRegistry);

function isPlainExports(value: unknown): value is ModuleExports {
  return typeof value === 'object' && value !== null;
}

/** Best-effort read of what a specifier currently resolves to. */
function resolveBase(specifier: string): ModuleExports | null {
  const remembered = baselineExports.get(specifier);
  if (remembered) return remembered;
  try {
    const real: unknown = require(specifier);
    return isPlainExports(real) ? real : null;
  } catch {
    return null;
  }
}

mockRegistry.module = (specifier: string, factory: () => unknown): void => {
  originalMockModule(specifier, () => {
    const override: unknown = factory();
    if (!isPlainExports(override)) return override;

    const base = resolveBase(specifier);
    if (!base) return override;

    const merged: ModuleExports = { ...base, ...override };

    // `default` is an object on most of these modules (e.g. AsyncStorage), so
    // merge it too instead of letting a partial default erase real methods.
    if (isPlainExports(base.default) && isPlainExports(override.default)) {
      merged.default = { ...base.default, ...override.default };
    }
    return merged;
  });
};

// Remember what the preload itself registered, so later partial mocks layer
// over these rather than over an unloadable real native module.
baselineExports.set('expo-modules-core', _emcMock as unknown as ModuleExports);
for (const specifier of ['react-native', 'expo-secure-store', '@react-native-async-storage/async-storage']) {
  try {
    const current: unknown = require(specifier);
    if (isPlainExports(current)) baselineExports.set(specifier, current);
  } catch {
    // Not resolvable outside a bundler; the real-module fallback handles it.
  }
}

