import fs from 'fs';
import { evaluateSeniorGate, summarizeFleet } from '/home/user/rork-app/scripts/ivx-senior-quality-gate.mjs';

const reg = JSON.parse(fs.readFileSync('/tmp/ag2.json','utf8'));
const agents = reg.agents ?? [];
const PROD_SHA = '6ca1cd71f2b9602d079c141805f918279888e7da';
const now = new Date().toISOString();

const records = agents.map((a) => {
  const base = {
    agentNumber: a.agentNumber, agentId: a.agentId, agentName: a.name ?? null, role: a.role ?? null,
    taskId: null, taskType: null, gapId: null, startedAt: null, finishedAt: null,
    sourceSha: PROD_SHA, productionSha: PROD_SHA, sourceReference: '', toolResultId: '',
    commitSha: '', changedFiles: [], tests: null, typecheck: null, lint: null,
    securityReview: null, errorHandlingReview: null, performanceReview: null,
    accessibilityReview: null, deploymentEvidence: null, finalStatus: null,
    observedRegistry: {
      totalRuns: a.totalRuns ?? 0, successfulRuns: a.successfulRuns ?? 0,
      failedRuns: a.failedRuns ?? 0, evidenceCount: a.evidenceCount ?? 0,
      lastHeartbeat: a.lastHeartbeat ?? null, health: a.health ?? 'unknown',
    },
    evidenceSource: 'GET https://api.ivxholding.com/api/ivx/agents',
    evidenceCapturedAt: now,
  };
  const v = evaluateSeniorGate(base);
  return { ...base, status: v.status, acceptedBySeniorGate: v.acceptedBySeniorGate, rejectionReasons: v.rejectionReasons };
});
for (const r of records) {
  fs.writeFileSync(`qa/evidence/autonomous/agents/agent-${String(r.agentNumber).padStart(3,'0')}.json`, JSON.stringify(r,null,2)+'\n');
}
const s = summarizeFleet(records, 112);

const localGate = {
  expoTests: { command: 'bun test (expo)', pass: 1245, fail: 0, errors: 0, ok: true },
  backendTests: { command: 'bun test (CI backend set)', pass: 330, fail: 0, ok: true },
  backendTypecheck: { command: 'tsc --noEmit -p tsconfig.json', errors: 0, ok: true },
  expoRunChecks: { command: 'runChecks(expo)', result: 'passed', ok: true },
  seniorGateUnitTests: { command: 'node --test ivx-senior-quality-gate.test.mjs', pass: 18, fail: 0, ok: true },
};
const localOk = Object.values(localGate).every((g) => g.ok);

const conditions = {
  localQaGateGreen: localOk,
  totalAgentsIs112: s.totalAgents === 112,
  acceptedBySeniorGate112: s.acceptedBySeniorGate === 112,
  unverifiedIsZero: s.unverified === 0,
  agentsWithSourceReference112: s.agentsWithSourceReference === 112,
  agentsWithToolResultId112: s.agentsWithToolResultId === 112,
  productionHealthy: JSON.parse(fs.readFileSync('/tmp/h2.json','utf8')).status === 'healthy',
  productionVersionMatchesSha: JSON.parse(fs.readFileSync('/tmp/v2.json','utf8')).commit === PROD_SHA,
  allSixWorkflowsPassedOnExactSha: false,
};
const ok = Object.values(conditions).every(Boolean);

const cert = {
  certificate: ok ? 'IVX-112-SENIOR-DEVELOPER-10OF10-CERTIFIED' : 'IVX-112-SENIOR-DEVELOPER-NOT-CERTIFIED',
  ok, verdict: ok ? 'CERTIFIED' : 'NOT CERTIFIED', evaluatedAt: now, productionSha: PROD_SHA,
  localQaGate: { ...localGate, allGreen: localOk },
  conditions,
  fleet: {
    totalAgents: s.totalAgents, acceptedBySeniorGate: s.acceptedBySeniorGate,
    failed: s.failed, blocked: s.blocked, unverified: s.unverified,
    agentsWithSourceReference: s.agentsWithSourceReference,
    agentsWithToolResultId: s.agentsWithToolResultId,
  },
  blockingReasons: [
    'unverified=112: every agent still reports totalRuns=0, evidenceCount=0, lastHeartbeat=null, health="unknown" in the live registry. No agent has ever executed a run.',
    'acceptedBySeniorGate=0 of required 112.',
    'The six required workflows have NOT been observed green on this exact SHA.',
  ],
  note: 'The LOCAL QA gate is green and that is stated separately and honestly. It does NOT certify the 112-agent fleet: a green test suite proves the code compiles and behaves, not that 112 autonomous agents did senior-grade work. Those are different claims and are scored separately.',
};
fs.writeFileSync('qa/evidence/autonomous/ivx-112-senior-developer-certificate.json', JSON.stringify(cert,null,2)+'\n');
console.log('LOCAL QA GATE :', localOk ? 'GREEN' : 'RED');
console.log('112 VERDICT   :', cert.verdict, '|', cert.certificate);
console.log('accepted/112  :', s.acceptedBySeniorGate, '| unverified:', s.unverified);
for (const [k,v] of Object.entries(conditions)) console.log(`  ${v?'PASS':'FAIL'}  ${k}`);
EOF
